style.css:
/* Fundo preto */
body {
    background: #000 !important;
    color: #fff !important;
}

/* Elementos brancos ficam pretos */
* {
    border-color: #fff !important;
}

/* Textos */
p,
span,
div,
h1,
h2,
h3,
h4,
h5,
h6,
a,
label,
li {
    color: #fff !important;
}

/* Fundos brancos */
body,
section,
header,
footer,
main,
nav,
article,
aside,
div {
    background-color: #000 !important;
}
